(() => {
  const ALLOWED = new Set(["claimId", "patientRef", "serviceDate", "procedureCode", "amount"]);
  function findDuplicateGroups(claims) {
    for (const claim of claims) {
      for (const name of Object.keys(claim)) {
        if (!ALLOWED.has(name)) {
          throw new Error("unknown field: " + name);
        }
      }
    }
    const byKey = new Map();
    for (const claim of claims) {
      const key = JSON.stringify([claim.patientRef, claim.serviceDate, claim.procedureCode, claim.amount]);
      let entry = byKey.get(key);
      if (!entry) {
        entry = {
          claimIds: [],
          patientRef: claim.patientRef,
          serviceDate: claim.serviceDate,
          procedureCode: claim.procedureCode,
          amount: claim.amount
        };
        byKey.set(key, entry);
      }
      entry.claimIds.push(claim.claimId);
    }
    const groups = [];
    for (const entry of byKey.values()) {
      if (entry.claimIds.length >= 2) {
        groups.push(entry);
      }
    }
    return { groups };
  }
  return { findDuplicateGroups };
})()

