build.unitScript:
test("two claims with same four fields but different claimIds form one group", () => {
  const result = code.findDuplicateGroups([
    { claimId: "C-1", patientRef: "P-001", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120 },
    { claimId: "C-2", patientRef: "P-001", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120 }
  ]);
  assert.deepEqual(result, { groups: [{ claimIds: ["C-1", "C-2"], patientRef: "P-001", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120 }] });
});
test("claims that differ only in amount are not flagged", () => {
  const result = code.findDuplicateGroups([
    { claimId: "C-3", patientRef: "P-002", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120 },
    { claimId: "C-4", patientRef: "P-002", serviceDate: "2024-03-05", procedureCode: "99213", amount: 125 }
  ]);
  assert.deepEqual(result, { groups: [] });
});
test("three matching claims form one group of three, not three pairs", () => {
  const result = code.findDuplicateGroups([
    { claimId: "C-5", patientRef: "P-003", serviceDate: "2024-03-06", procedureCode: "99214", amount: 80 },
    { claimId: "C-6", patientRef: "P-003", serviceDate: "2024-03-06", procedureCode: "99214", amount: 80 },
    { claimId: "C-7", patientRef: "P-003", serviceDate: "2024-03-06", procedureCode: "99214", amount: 80 }
  ]);
  assert.equal(result.groups.length, 1);
  assert.deepEqual(result.groups[0].claimIds, ["C-5", "C-6", "C-7"]);
});
test("identical claims passed in separate batches are not flagged", () => {
  const batchA = code.findDuplicateGroups([
    { claimId: "C-8", patientRef: "P-004", serviceDate: "2024-03-07", procedureCode: "99213", amount: 120 }
  ]);
  const batchB = code.findDuplicateGroups([
    { claimId: "C-9", patientRef: "P-004", serviceDate: "2024-03-07", procedureCode: "99213", amount: 120 }
  ]);
  assert.deepEqual(batchA, { groups: [] });
  assert.deepEqual(batchB, { groups: [] });
});
test("a claim with an unknown field throws an error naming that field", () => {
  assert.throws(() => code.findDuplicateGroups([
    { claimId: "C-10", patientRef: "P-005", serviceDate: "2024-03-08", procedureCode: "99213", amount: 50, status: "open" }
  ]), /unknown field: status/);
});
test("unmatched claims are left out of the review list and input claims are not changed", () => {
  const claims = [
    { claimId: "C-11", patientRef: "P-006", serviceDate: "2024-03-09", procedureCode: "99213", amount: 60 },
    { claimId: "C-12", patientRef: "P-007", serviceDate: "2024-03-09", procedureCode: "99213", amount: 60 },
    { claimId: "C-13", patientRef: "P-006", serviceDate: "2024-03-09", procedureCode: "99213", amount: 60 }
  ];
  const result = code.findDuplicateGroups(claims);
  assert.equal(result.groups.length, 1);
  assert.deepEqual(result.groups[0].claimIds, ["C-11", "C-13"]);
  assert.equal(claims.length, 3);
  assert.deepEqual(claims[1], { claimId: "C-12", patientRef: "P-007", serviceDate: "2024-03-09", procedureCode: "99213", amount: 60 });
});

build.testScript:
test("exact match ignores claimId and flags one group with the matched values", function() {
  var claims = [
    { claimId: "C-1", patientRef: "P-001", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120 },
    { claimId: "C-2", patientRef: "P-001", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120 }
  ];
  var result = code.findDuplicateGroups(claims);
  assert.equal(result.groups.length, 1);
  assert.deepEqual(result.groups[0].claimIds.slice().sort(), ["C-1", "C-2"]);
  assert.equal(result.groups[0].patientRef, "P-001");
  assert.equal(result.groups[0].serviceDate, "2024-03-05");
  assert.equal(result.groups[0].procedureCode, "99213");
  assert.equal(result.groups[0].amount, 120);
});
test("all four compared fields must match exactly so a different amount flags nothing", function() {
  var claims = [
    { claimId: "C-3", patientRef: "P-002", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120 },
    { claimId: "C-4", patientRef: "P-002", serviceDate: "2024-03-05", procedureCode: "99213", amount: 125 }
  ];
  var result = code.findDuplicateGroups(claims);
  assert.deepEqual(result.groups, []);
});
test("three claims that match form one group of three and not three pairs", function() {
  var claims = [
    { claimId: "C-5", patientRef: "P-003", serviceDate: "2024-03-06", procedureCode: "99214", amount: 80 },
    { claimId: "C-6", patientRef: "P-003", serviceDate: "2024-03-06", procedureCode: "99214", amount: 80 },
    { claimId: "C-7", patientRef: "P-003", serviceDate: "2024-03-06", procedureCode: "99214", amount: 80 }
  ];
  var result = code.findDuplicateGroups(claims);
  assert.equal(result.groups.length, 1);
  assert.equal(result.groups[0].claimIds.length, 3);
  assert.deepEqual(result.groups[0].claimIds.slice().sort(), ["C-5", "C-6", "C-7"]);
  assert.equal(result.groups[0].patientRef, "P-003");
  assert.equal(result.groups[0].serviceDate, "2024-03-06");
  assert.equal(result.groups[0].procedureCode, "99214");
  assert.equal(result.groups[0].amount, 80);
});
test("identical claims passed as separate batches are not flagged", function() {
  var batchA = [
    { claimId: "C-8", patientRef: "P-004", serviceDate: "2024-03-07", procedureCode: "99213", amount: 120 }
  ];
  var batchB = [
    { claimId: "C-9", patientRef: "P-004", serviceDate: "2024-03-07", procedureCode: "99213", amount: 120 }
  ];
  var resultA = code.findDuplicateGroups(batchA);
  var resultB = code.findDuplicateGroups(batchB);
  assert.deepEqual(resultA.groups, []);
  assert.deepEqual(resultB.groups, []);
});
test("a claim that belongs to no group is not flagged and does not appear", function() {
  var claims = [
    { claimId: "C-1", patientRef: "P-001", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120 },
    { claimId: "C-2", patientRef: "P-001", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120 },
    { claimId: "C-10", patientRef: "P-010", serviceDate: "2024-04-01", procedureCode: "99215", amount: 50 }
  ];
  var result = code.findDuplicateGroups(claims);
  assert.equal(result.groups.length, 1);
  assert.deepEqual(result.groups[0].claimIds.slice().sort(), ["C-1", "C-2"]);
  assert.equal(result.groups[0].patientRef, "P-001");
  assert.equal(result.groups[0].serviceDate, "2024-03-05");
  assert.equal(result.groups[0].procedureCode, "99213");
  assert.equal(result.groups[0].amount, 120);
  assert.equal(result.groups[0].claimIds.indexOf("C-10"), -1);
});
test("amounts a few cents apart and dates one day apart are not flagged", function() {
  var claims = [
    { claimId: "C-11", patientRef: "P-005", serviceDate: "2024-03-08", procedureCode: "99213", amount: 120 },
    { claimId: "C-12", patientRef: "P-005", serviceDate: "2024-03-08", procedureCode: "99213", amount: 120.03 },
    { claimId: "C-13", patientRef: "P-006", serviceDate: "2024-03-08", procedureCode: "99213", amount: 90 },
    { claimId: "C-14", patientRef: "P-006", serviceDate: "2024-03-09", procedureCode: "99213", amount: 90 }
  ];
  var result = code.findDuplicateGroups(claims);
  assert.deepEqual(result.groups, []);
});
test("exact matches are flagged only and the claims are not deleted edited or rejected", function() {
  var claims = [
    { claimId: "C-1", patientRef: "P-001", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120 },
    { claimId: "C-2", patientRef: "P-001", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120 }
  ];
  var before = [
    { claimId: "C-1", patientRef: "P-001", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120 },
    { claimId: "C-2", patientRef: "P-001", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120 }
  ];
  var result = code.findDuplicateGroups(claims);
  assert.deepEqual(claims, before);
  assert.equal(claims.length, 2);
  assert.equal(Object.keys(result).length, 1);
  assert.equal(Object.keys(result)[0], "groups");
  assert.equal(result.groups.length, 1);
  assert.deepEqual(result.groups[0].claimIds.slice().sort(), ["C-1", "C-2"]);
});
test("two different matching sets become two separate groups with their own values", function() {
  var claims = [
    { claimId: "C-15", patientRef: "P-007", serviceDate: "2024-03-10", procedureCode: "99213", amount: 40 },
    { claimId: "C-16", patientRef: "P-007", serviceDate: "2024-03-10", procedureCode: "99213", amount: 40 },
    { claimId: "C-17", patientRef: "P-008", serviceDate: "2024-03-11", procedureCode: "99214", amount: 60 },
    { claimId: "C-18", patientRef: "P-008", serviceDate: "2024-03-11", procedureCode: "99214", amount: 60 }
  ];
  var result = code.findDuplicateGroups(claims);
  var byPatient = {};
  var i;
  assert.equal(result.groups.length, 2);
  for (i = 0; i < result.groups.length; i++) {
    byPatient[result.groups[i].patientRef] = result.groups[i];
  }
  assert.deepEqual(byPatient["P-007"].claimIds.slice().sort(), ["C-15", "C-16"]);
  assert.equal(byPatient["P-007"].serviceDate, "2024-03-10");
  assert.equal(byPatient["P-007"].procedureCode, "99213");
  assert.equal(byPatient["P-007"].amount, 40);
  assert.deepEqual(byPatient["P-008"].claimIds.slice().sort(), ["C-17", "C-18"]);
  assert.equal(byPatient["P-008"].serviceDate, "2024-03-11");
  assert.equal(byPatient["P-008"].procedureCode, "99214");
  assert.equal(byPatient["P-008"].amount, 60);
});

